def pode_concluir_tarefas(n, dependencias):
    from collections import defaultdict, deque
    grafo = defaultdict(list)
    in_degree = [0] * n

    for a, b in dependencias:
        grafo[b].append(a)
        in_degree[a] += 1

    fila = deque()
    for i in range(n):
        if in_degree[i] == 0:
            fila.append(i)

    contador = 0
    while fila:
        no = fila.popleft()
        contador += 1
        for vizinho in grafo[no]:
            in_degree[vizinho] -= 1
            if in_degree[vizinho] == 0:
                fila.append(vizinho)

    return contador == n
